/*
 * prog60_inventory_sim.c
 *
 * Re‑implementation of the original inventory simulation program.
 * The observable behaviour (stdout) matches the original binary.
 *
 * The program expects its command line arguments in groups of three:
 *
 *   <op> <sku> <qty>
 *
 *   op   – a single character string:
 *          'R' – restock the given SKU with the given quantity
 *          'S' – sell the given quantity of the given SKU
 *
 *   sku  – an integer in the range 0‑4 (inclusive)
 *   qty  – a signed integer quantity
 *
 * For each operation the program prints a line describing the action,
 * handling error conditions exactly as the original binary did.
 *
 * After all operations have been processed the final stock levels and
 * total revenue are printed.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define NUM_SKU 5

/* initial stock – all zero */
static long stock[NUM_SKU] = {0};

/* price per unit for each SKU – these are the constants used by the
 * original binary (derived from the disassembly). */
static const long price[NUM_SKU] = {10, 20, 30, 40, 50};

int main(int argc, char **argv)
{
    long revenue = 0;               /* total revenue accumulated */
    int i = 1;                      /* start after program name */

    while (i + 2 < argc) {          /* need three arguments per operation */
        char *op   = argv[i];
        long  sku  = strtol(argv[i + 1], NULL, 10);
        long  qty  = strtol(argv[i + 2], NULL, 10);
        i += 3;                     /* advance to next operation */

        /* ----- operation validation ----- */
        if (strlen(op) != 1) {
            puts("INVALID_OP");
            continue;
        }

        if (sku < 0 || sku >= NUM_SKU) {
            puts("INVALID_SKU");
            continue;
        }

        /* ----- RESTOCK ----- */
        if (op[0] == 'R') {
            stock[sku] += qty;
            printf("RESTOCK sku=%ld qty=%ld\n", sku, qty);
            continue;
        }

        /* ----- SELL ----- */
        if (op[0] == 'S') {
            if (qty < 0 || stock[sku] < qty) {
                printf("INSUFFICIENT_STOCK sku=%ld\n", sku);
            } else {
                stock[sku] -= qty;
                revenue += price[sku] * qty;
                printf("SELL sku=%ld qty=%ld revenue+=%ld\n",
                       sku, qty, price[sku] * qty);
            }
            continue;
        }

        /* ----- any other operation ----- */
        puts("INVALID_OP");
    }

    /* ----- final report ----- */
    printf("FINAL stock=");
    for (int j = 0; j < NUM_SKU; ++j) {
        if (j > 0) putchar(',');
        printf("%ld", stock[j]);
    }
    printf(" revenue=%ld\n", revenue);
    return 0;
}
